# --- 편의 메서드 없이 ---

@Test
@Transactional
void 한쪽만_채우면() {
    Member member = 회원만들기();
    em.persist(member);

    Order order = new Order();
    // order.setMember(member) 대신 리플렉션이나 필드 직접
    // (실제로는 편의 메서드를 쓰므로 이런 코드가 안 나온다)

    em.persist(order);
    em.flush();

    log.info("orders size = {}", member.getOrders().size());
}

#   Hibernate: insert into member (...) values (?,?,?,?,?)
#   Hibernate: insert into orders (delivery_id, member_id, order_date,
#                                  status, order_id)
#              values (?, ?, ?, ?, ?)
#   binding parameter [2] as [BIGINT] - [1]

#   member_id 가 채워졌다

#   orders size = 0

#   DB 는 맞는데 객체가 비어 있다

# --- 커밋하고 새로 조회하면 ---

em.flush();
em.clear();
Member found = em.find(Member.class, member.getId());
log.info("orders size = {}", found.getOrders().size());

#   Hibernate: select m1_0.member_id, ... from member m1_0 where ...
#   Hibernate: 
#       select o1_0.member_id, o1_0.order_id, o1_0.delivery_id,
#              o1_0.order_date, o1_0.status
#       from orders o1_0 where o1_0.member_id=?

#   orders size = 1

#   이번엔 맞다

#   같은 트랜잭션에서만 틀렸다

# --- 편의 메서드를 쓰면 ---

Order order = new Order();
order.setMember(member);

log.info("orders size = {}", member.getOrders().size());
#   orders size = 1

#   (아직 아무 SQL 도 안 나갔다)

#   자바 객체끼리 맞춰졌다

# --- cascade 확인 ---

Delivery delivery = new Delivery();
delivery.setAddress(member.getAddress());
delivery.setStatus(DeliveryStatus.READY);

Order order = new Order();
order.setMember(member);
order.setDelivery(delivery);        // persist 를 안 했다

em.persist(order);
em.flush();

#   Hibernate: select next value for delivery_seq
#   Hibernate: select next value for orders_seq
#   Hibernate: 
#       insert into delivery (city, street, zipcode, status, delivery_id)
#       values (?, ?, ?, ?, ?)
#   Hibernate: 
#       insert into orders (delivery_id, member_id, order_date, status,
#                           order_id)
#       values (?, ?, ?, ?, ?)

#   delivery 를 persist 한 적이 없다
#   cascade = ALL 이 대신 했다

#   insert 가 둘이다. 내가 쓴 persist 는 하나다.

# --- cascade 를 빼면 ---

@OneToOne(fetch = FetchType.LAZY)     // cascade 없음
private Delivery delivery;

em.persist(order);
em.flush();

#   org.hibernate.TransientPropertyValueException:
#     object references an unsaved transient instance -
#     save the transient instance before flushing :
#     Order.delivery -> Delivery

#   배송을 먼저 저장하라는 뜻이다

# --- 7.7절에서 셋이 된다 ---

#   insert into delivery
#   insert into orders
#   insert into order_item

#   persist 는 여전히 하나다
